tags.gen_ai.tool.definitions:
[
  {
    "type": "function",
    "name": "get_requirements_document_overview",
    "description": "Liefert Uebersicht, Abschnittsueberschriften und Kennzahlen des aktuellen Requirements-Dokuments.",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "list_requirements",
    "description": "Listet Requirements mit Status, Readiness und kurzer Beschreibung.",
    "parameters": {
      "type": "object",
      "properties": {
        "status": {
          "type": "string",
          "default": ""
        },
        "limit": {
          "type": "integer",
          "default": 120
        }
      }
    }
  },
  {
    "type": "function",
    "name": "get_requirement",
    "description": "Liest ein einzelnes Requirement inklusive Readiness und Provenance.",
    "parameters": {
      "type": "object",
      "properties": {
        "requirementId": {
          "type": "string"
        }
      },
      "required": [
        "requirementId"
      ]
    }
  },
  {
    "type": "function",
    "name": "get_requirements_document_excerpt",
    "description": "Liest einen Ausschnitt aus dem Requirements-Dokument.",
    "parameters": {
      "type": "object",
      "properties": {
        "startLine": {
          "type": "integer",
          "default": 1
        },
        "lineCount": {
          "type": "integer",
          "default": 120
        }
      }
    }
  },
  {
    "type": "function",
    "name": "save_adequacy_report",
    "description": "Speichert dein finales Adequacy-Feedback. Rufe dies genau einmal am Ende auf.",
    "parameters": {
      "type": "object",
      "properties": {
        "findings": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "findingId": {
                "type": "string"
              },
              "section": {
                "type": "string"
              },
              "adequacy": {
                "type": "string"
              },
              "summary": {
                "type": "string"
              },
              "whyItMatters": {
                "type": "string"
              },
              "relatedRequirementIds": {
                "type": "array",
                "items": {
                  "type": "string"
                }
              },
              "recommendedAction": {
                "type": "string"
              },
              "requiresHumanDecision": {
                "type": "boolean"
              }
            },
            "required": [
              "findingId",
              "section",
              "adequacy",
              "summary",
              "whyItMatters",
              "relatedRequirementIds",
              "recommendedAction",
              "requiresHumanDecision"
            ]
          }
        },
        "overallAssessment": {
          "type": "string"
        }
      },
      "required": [
        "findings",
        "overallAssessment"
      ]
    }
  }
]

tags.gen_ai.input.messages:
[
  {
    "role": "user",
    "parts": [
      {
        "type": "text",
        "content": "Bewerte den aktuellen L4 Requirements-Stand als Requirements Engineer.\n\nErkunde das Requirements-Dokument, Requirements, Readiness und Provenance mit deinen Tools.\nBeurteile kapitelweise, ob der Stand fuer einen Projektstart substanziell genug ist.\nSpeichere am Ende genau einmal ein Adequacy-Feedback mit save_adequacy_report."
      }
    ]
  }
]
